#!/usr/bin/env python3
"""
Test all models from a JSON config file against an OpenAI-compatible chat endpoint.

Usage:
    python test_models.py models.json

Accepted JSON formats:
1) ["model-a", "model-b"]
2) {"models": ["model-a", "model-b"]}
3) {"models": [{"name": "model-a"}, {"id": "model-b"}]}
"""

import json
import sys
import time
import urllib.request
import urllib.error

API_URL = "http://127.0.0.1:4000/v1/chat/completions"
PROMPT = "Reply with exactly one word: OK"
TIMEOUT_SECONDS = 30
MAX_TOKENS = 20


def load_models(path):
    with open(path, "r", encoding="utf-8") as f:
        data = json.load(f)

    models = []

    if isinstance(data, list):
        for item in data:
            if isinstance(item, str):
                models.append(item)
            elif isinstance(item, dict):
                # Support common keys
                name = item.get("name") or item.get("id") or item.get("model")
                if isinstance(name, str):
                    models.append(name)

    elif isinstance(data, dict):
        if isinstance(data.get("models"), list):
            for item in data["models"]:
                if isinstance(item, str):
                    models.append(item)
                elif isinstance(item, dict):
                    name = item.get("name") or item.get("id") or item.get("model")
                    if isinstance(name, str):
                        models.append(name)
        elif isinstance(data.get("model"), str):
            models.append(data["model"])

    # De-duplicate while preserving order
    seen = set()
    unique = []
    for m in models:
        if m not in seen:
            seen.add(m)
            unique.append(m)

    return unique


def extract_response_text(resp_json):
    """
    Expected shape:
    {
      "choices": [
        {"message": {"role": "assistant", "content": "..."}}
      ]
    }
    """
    choices = resp_json.get("choices")
    if not choices or not isinstance(choices, list):
        return ""

    first = choices[0] if choices else {}
    message = first.get("message", {})
    content = message.get("content", "")

    # Some backends may return non-string content structures
    if isinstance(content, str):
        return content
    if isinstance(content, list):
        # Try to stitch text parts if present
        parts = []
        for part in content:
            if isinstance(part, dict) and isinstance(part.get("text"), str):
                parts.append(part["text"])
        return "".join(parts)
    return str(content)


def build_payload(model, include_temperature=True):
    payload = {
        "model": model,
        "messages": [{"role": "user", "content": PROMPT}],
        "max_tokens": MAX_TOKENS,
    }
    if include_temperature:
        payload["temperature"] = 0
    return payload


def post_json(url, payload, timeout):
    body = json.dumps(payload).encode("utf-8")
    req = urllib.request.Request(
        url,
        data=body,
        headers={"Content-Type": "application/json"},
        method="POST",
    )
    with urllib.request.urlopen(req, timeout=timeout) as resp:
        raw = resp.read().decode("utf-8", errors="replace")
        return json.loads(raw)


def looks_like_temperature_unsupported(error_text):
    t = error_text.lower()
    return ("temperature" in t) and (
        "unsupported" in t
        or "not supported" in t
        or "unknown" in t
        or "invalid" in t
        or "extra inputs" in t
        or "unexpected" in t
    )


def test_model(model):
    start = time.time()

    def fail(status_text):
        return {
            "model": model,
            "status": status_text,
            "latency": time.time() - start,
            "response": status_text,
        }

    # First try with temperature
    for include_temperature in (True, False):
        payload = build_payload(model, include_temperature=include_temperature)
        try:
            resp_json = post_json(API_URL, payload, timeout=TIMEOUT_SECONDS)
            text = extract_response_text(resp_json).strip()
            ok = text == "OK"
            status = "PASS" if ok else "FAIL"
            return {
                "model": model,
                "status": status,
                "latency": time.time() - start,
                "response": text,
            }

        except urllib.error.HTTPError as e:
            err_body = ""
            try:
                err_body = e.read().decode("utf-8", errors="replace")
            except Exception:
                err_body = str(e)

            # If temperature unsupported and this was the first attempt, retry without it
            if include_temperature and looks_like_temperature_unsupported(err_body):
                continue

            return fail(f"HTTP {e.code}: {err_body.strip() or e.reason}")

        except urllib.error.URLError as e:
            return fail(f"URL error: {e.reason}")

        except Exception as e:
            return fail(f"Error: {e}")

    # If we exhausted retries
    return fail("FAIL: unsupported parameters")


def truncate(text, n=50):
    text = (text or "").replace("\n", " ").replace("\r", " ").strip()
    return text[:n]


def print_table(results):
    model_w = max(len("Model"), max((len(r["model"]) for r in results), default=5))
    status_w = len("Status")
    latency_w = len("Latency")

    sep = f"+-{'-' * model_w}-+-{'-' * status_w}-+-{'-' * latency_w}-+-{'-' * 50}-+"
    header = (
        f"| {'Model'.ljust(model_w)} | {'Status'.ljust(status_w)} | "
        f"{'Latency'.ljust(latency_w)} | {'Response'.ljust(50)} |"
    )

    print(sep)
    print(header)
    print(sep)

    for r in results:
        latency_s = f"{r['latency']:.2f}s"
        resp = truncate(r["response"], 50)
        print(
            f"| {r['model'].ljust(model_w)} | "
            f"{r['status'].ljust(status_w)} | "
            f"{latency_s.ljust(latency_w)} | "
            f"{resp.ljust(50)} |"
        )

    print(sep)


def main():
    if len(sys.argv) != 2:
        print("Usage: python test_models.py <models.json>")
        sys.exit(1)

    config_path = sys.argv[1]
    try:
        models = load_models(config_path)
    except FileNotFoundError:
        print(f"Config file not found: {config_path}")
        sys.exit(1)
    except json.JSONDecodeError as e:
        print(f"Invalid JSON in {config_path}: {e}")
        sys.exit(1)

    if not models:
        print("No models found in config.")
        sys.exit(1)

    results = []
    for model in models:
        results.append(test_model(model))

    print_table(results)

    working = sum(1 for r in results if r["status"] == "PASS")
    failed = len(results) - working
    print(f"Total: {len(results)} models | ✅ {working} working | ❌ {failed} failed")


if __name__ == "__main__":
    main()
